// 当前对象字典的整体置信度。全部 verified 才为 true。
inline constexpr bool kOdVerified = (PMP4010_OD_VERIFIED != 0);

// 取一条已核对条目的索引。未核对时返回哨兵 —— 调用方必须自己判 usable，
// 因此本函数**不**替它兜底。
constexpr std::uint16_t pmp4010_index(std::size_t entry) noexcept {
    if (entry >= kEntryCount || !kEntries[entry].verified) {
        return kIndexUnset;
    }
    return kEntries[entry].index;
}

